    Pipe pipe = getPipeQueue().peek();
    if (getMap().tryPlacePipe(row, convertedCol, pipe))
    {
      getPipeQueue().consume();
      FillableCell placedCell = (FillableCell) getMap().getCell()[row][convertedCol];
      getCellStack().push(placedCell);
      setNumOfSteps(getNumOfSteps() + 1);
      return true;
    }
    return false;
